Future<void>pick()async{final p=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['csv','xlsx','xls']);if(p?.files.single.path==null)return;setState((){path=p!.files.single.path;name=p.files.single.name;out=null;error=null;});}
Future<void>run()async{if(path==null){setState(()=>error='Choose a CSV or Excel dataset first.');return;}setState((){busy=true;error=null;out=null;});try{final raw=await ch.invokeMethod<String>('analyze',{'path':path,'question':q.trim(),'mode':mode});final x=jsonDecode(raw??'{}');setState(()=>out=Map<String,dynamic>.from(x));}on PlatformException catch(e){setState(()=>error=e.message??e.code);}catch(e){setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}}
