),const Text('Optional. Leave it empty and StatsYuri will analyze the dataset automatically.',style:TextStyle(color:Colors.white60,fontSize:13,height:1.4)),const SizedBox(height:13),TextField(minLines:3,maxLines:6,onChanged:(v)=>q=v,style:const TextStyle(fontSize:15,height:1.45),decoration:const InputDecoration(hintText:'Example: Do crop yields differ among fertilizer groups?')),const SizedBox(height:14),Container(padding:const EdgeInsets.all(4),decoration:BoxDecoration(color:surface,borderRadius:BorderRadius.circular(17)),child:SegmentedButton<String>(showSelectedIcon:false,segments:const[ButtonSegment(value:'efficient',label:Text('Efficient'),icon:Icon(Icons.bolt_rounded,size:18)),ButtonSegment(value:'full',label:Text('Full analysis'),icon:Icon(Icons.analytics_rounded,size:18))],selected:{mode},onSelectionChanged:(v)=>setState(()=>mode=v.first))),const SizedBox(height:10),Text(mode=='full'?'Full mode evaluates every compatible analysis it can calculate.':'Efficient mode selects one compatible analysis and explains it.',style:const TextStyle(color:Colors.white38,fontSize:12)),const SizedBox(height:14),SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:busy?null:run,style:FilledButton.styleFrom(backgroundColor:accent,foregroundColor:const Color(0xFF25183E),padding:const EdgeInsets.symmetric(vertical:16),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(18))),icon:busy?const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2)):const Icon(Icons.search_rounded),label:Text(busy?'Analyzing…':'Analyze dataset',style:const TextStyle(fontWeight:FontWeight.w900,fontSize:15))))])),if(error!=null)Padding(padding:const EdgeInsets.only(top:14),child:CardBox(child:Text(error!,style:const TextStyle(color:Color(0xFFFFB0B0),fontSize:14,height:1.4)))),if(out!=null)ResultView(out!)]))]));}
