String pretty(String s)=>s.replaceAll(' + simple linear regression',' + Regression');
String keyName(String s){const m={'F-Statistic':'F statistic','P-Value':'p-value','T-Statistic':'t statistic','Degrees of Freedom':'Degrees of freedom','R-Squared':'R²','Slope P-Value':'Slope p-value','Sample Mean':'Sample mean','Hypothesized Mean':'Reference mean','Group Sizes':'Group sizes','Group Means':'Group means','Total Sample Size':'Total sample size','Number of Groups':'Number of groups'};return m[s]??s.replaceAll('_',' ');}
String val(dynamic x){if(x==null)return'Not available';if(x is double){if(!x.isFinite)return x.toString();if(x.abs()<.0001&&x!=0)return x.toStringAsExponential(3);return x.toStringAsFixed(5).replaceFirst(RegExp(r'0+$'),'').replaceFirst(RegExp(r'\.$'),'');}if(x is num)return x.toString();if(x is Map)return x.entries.map((e)=>'${keyName(e.key.toString())}: ${val(e.value)}').join('\n');if(x is List)return x.map(val).join('  •  ');return x.toString();}
class BgPainter extends CustomPainter{BgPainter(this.p);final double p;@override void paint(Canvas c,Size s){final t=p*math.pi*2;final base=Paint()..shader=const LinearGradient(begin:Alignment.topLeft,end:Alignment.bottomRight,colors:[bg,bg2]).createShader(Offset.zero&s);c.drawRect(Offset.zero&s,base);for(final b in[(Offset(s.width*(.08+.035*math.sin(t)),s.height*.13),190.0,const Color(0xFF6C4CA0)),(Offset(s.width*(.9+.035*math.cos(t*.8)),s.height*.42),220.0,const Color(0xFF315E7D)),(Offset(s.width*(.52+.06*math.sin(t*.55)),s.height*.88),210.0,const Color(0xFF49376F))]){final q=Paint()..shader=RadialGradient(colors:[b.$3.withOpacity(.095),b.$3.withOpacity(0)]).createShader(Rect.fromCircle(center:b.$1,radius:b.$2));c.drawCircle(b.$1,b.$2,q);}final g=Paint()..color=Colors.white.withOpacity(.018);const step=42.0;final d=p*step%step;for(double x=-step+d;x<s.width+step;x+=step)c.drawLine(Offset(x,0),Offset(x,s.height),g);for(double y=-step+d;y<s.height+step;y+=step)c.drawLine(Offset(0,y),Offset(s.width,y),g);final sy=['μ','σ','x̄','r','p','Σ','F','t','χ²','β'];for(var i=0;i<sy.length;i++){final ph=t*(.16+i*.013)+i*1.7;final x=((i*97+math.sin(ph)*24)%(s.width+80))-40,y=((i*137+p*180+math.cos(ph)*32)%(s.height+120))-60;final tp=TextPainter(text:TextSpan(text:sy[i],style:TextStyle(color:accent.withOpacity(.03),fontSize:22+(i%3)*7,fontWeight:FontWeight.w700)),textDirection:TextDirection.ltr)..layout();tp.paint(c,Offset(x,y));}}@override bool shouldRepaint(covariant BgPainter o)=>o.p!=p;}
